SELECT id, user_id, user_name, user_phone, user_role, CASE user_role WHEN 1 THEN '普通用户' WHEN 2 THEN '审核员' WHEN 3 THEN '管理员' ELSE '未知角色' END AS user_role_name, tenant_id, del_flag, create_by, create_time, update_by, update_time FROM spd_user
del_flag = #{queryForm.delFlag}
AND user_name LIKE CONCAT('%', #{queryForm.userName}, '%')
AND user_phone = #{queryForm.userPhone}
AND user_role = #{queryForm.userRole}
AND tenant_id = #{queryForm.tenantId}
ORDER BY create_time DESC

SELECT *
FROM spd_user
WHERE user_phone = #{userPhone}
  AND del_flag = #{delFlag}

    AND id != #{excludeUserId}
